const iframes = await page.evaluate(() => {
  const frames = Array.from(document.querySelectorAll('iframe'));
  return frames.map(f => {
    try {
      const doc = f.contentDocument;
      if (!doc) return { src: f.src, hasDoc: false };
      const body = doc.body;
      const computed = window.getComputedStyle(body);
      return {
        src: f.src,
        hasDoc: true,
        bodyBg: computed.backgroundColor,
        bodyColor: computed.color,
        stylesheets: Array.from(doc.querySelectorAll('link[rel="stylesheet"], style')).map(s => s.outerHTML),
        innerFrames: Array.from(doc.querySelectorAll('iframe')).map(inner => {
          try {
            const innerDoc = inner.contentDocument;
            const innerComputed = innerDoc ? innerDoc.defaultView.getComputedStyle(innerDoc.body) : null;
            return {
              src: inner.src,
              innerBg: innerComputed?.backgroundColor,
              innerColor: innerComputed?.color,
              innerStyles: Array.from(innerDoc?.querySelectorAll('link[rel="stylesheet"], style') || []).map(s => s.outerHTML)
            };
          } catch (e) {
            return { error: e.message };
          }
        })
      };
    } catch(e) {
      return { src: f.src, error: e.message };
    }
  });
});
return JSON.stringify(iframes, null, 2);

