{"code":"const info = await page.evaluate(() => {
  const outerFrame = document.querySelector('iframe');
  const outerDoc = outerFrame?.contentDocument;
  const innerFrame = outerDoc?.querySelector('iframe');
  const innerDoc = innerFrame?.contentDocument;
  if (!innerDoc) return { error: 'no inner doc' };

  const matchedRules = [];
  for (const sheet of Array.from(innerDoc.styleSheets)) {
    try {
      for (const rule of Array.from(sheet.cssRules || [])) {
        if (rule.selectorText && innerDoc.body.matches(rule.selectorText)) {
          matchedRules.push({
            href: sheet.href,
            selector: rule.selectorText,
            cssText: rule.cssText
          });
        }
      }
    } catch(e) {
      matchedRules.push({ href: sheet.href, error: e.message });
    }
  }

  const computed = innerDoc.defaultView.getComputedStyle(innerDoc.body);

  return {
    matchedRules,
    computedBg: computed.backgroundColor,
    computedColor: computed.color,
    computedLineHeight: computed.lineHeight,
    computedFontFamily: computed.fontFamily
  };
});
return JSON.stringify(info, null, 2);
